<?php
declare(strict_types=1);
namespace CommunityHub;
final class Notifications {
 public static function link(mixed $url):?string{return is_string($url)&&str_starts_with($url,'/')&&!str_starts_with($url,'//')&&!str_contains($url,'\\')&&!preg_match('/[\x00-\x20]/',$url)?$url:null;}
 private static function active(array $u):void{$actor=App::row('SELECT is_active FROM users WHERE id=?',[$u['id']]);if(empty($actor['is_active']))throw new HttpError('Active account required.',403);}
 public static function inbox(array $u,string $filter='all'):array{self::active($u);if(!in_array($filter,['all','unread'],true))throw new HttpError('Select a valid inbox filter.');$count=App::row('SELECT COALESCE(SUM(is_read=0),0) unread,COALESCE(MAX(id),0) cutoff FROM notifications WHERE user_id=?',[$u['id']]);$rows=App::rows("SELECT id,title,message,url,is_read,created_at FROM notifications WHERE user_id=? AND id<=? AND (?='all' OR is_read=0) ORDER BY id DESC LIMIT 100",[$u['id'],$count['cutoff'],$filter]);foreach($rows as &$n)$n['url']=self::link($n['url']);return ['ok'=>true,'notifications'=>$rows,'unread'=>(int)$count['unread'],'cutoff'=>(string)$count['cutoff'],'filter'=>$filter];}
 public static function read(array $u,array $d):array{if(!in_array($d['filter']??'all',['all','unread'],true))throw new HttpError('Select a valid inbox filter.');self::active($u);if(($d['all']??false)===true||($d['all']??'')==='1')App::query('UPDATE notifications SET is_read=1 WHERE user_id=? AND id<=? AND is_read=0',[$u['id'],App::id($d['cutoff']??null)]);else{$id=App::id($d['id']??null);if(!App::row('SELECT id FROM notifications WHERE id=? AND user_id=?',[$id,$u['id']]))throw new HttpError('Notification not found.',404);App::query('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?',[$id,$u['id']]);}return self::inbox($u,(string)($d['filter']??'all'));}
 public static function web(string $method,string $path,array $d):void{$u=Auth::requireUser(true);header('Cache-Control: private, no-store');if($method==='POST'&&$path==='/notifications/read'){self::read($u,$d);App::redirect('/notifications?filter='.rawurlencode((string)($d['filter']??'all')));}$data=self::inbox($u,(string)($_GET['filter']??'all'));if($path==='/notifications/data')App::json($data);if($path!=='/notifications')throw new HttpError('Page not found.',404);View::layout('Notifications',function()use($data){View::heading('Notifications',$data['unread'].' unread · Ticket, training and community updates.');?><section class="panel"><div class="ticket-filters"><a class="btn secondary" href="/notifications?filter=<?=escape($data['filter'])?>">Refresh</a><a class="btn secondary" href="/notifications?filter=all">All</a><a class="btn secondary" href="/notifications?filter=unread">Unread</a><?php if($data['unread'])View::form('/notifications/read',['all'=>['type'=>'hidden'],'cutoff'=>['type'=>'hidden'],'filter'=>['type'=>'hidden']],'Mark all as read',['all'=>'1','cutoff'=>$data['cutoff'],'filter'=>$data['filter']]);?></div><?php if(!$data['notifications']):?><p class="muted">No matching notifications.</p><?php endif;foreach($data['notifications'] as $n):?><article class="admin-row notification-entry"><div><strong><?=escape($n['title'])?></strong><p><?=escape($n['message'])?></p><small><?=escape($n['created_at'])?></small><?php if($n['url']):?><p><a href="<?=escape($n['url'])?>">View details →</a></p><?php endif?></div><?php if(!$n['is_read'])View::form('/notifications/read',['id'=>['type'=>'hidden'],'filter'=>['type'=>'hidden']],'Mark as read',['id'=>$n['id'],'filter'=>$data['filter']]);else echo '<span class="pill">Read</span>';?></article><?php endforeach?></section><?php });}
}
